be03f565-1c56-46a4-8af2-0fa02fcfcc30	authentik default LDAP Mapping: DN to User Path	path_elements = []\nfor pair in dn.split(","):\n    attr, _, value = pair.partition("=")\n    # Ignore elements from the Root DSE and the canonical name of the object\n    if attr.lower() in ["cn", "dc"]:\n        continue\n    path_elements.append(value)\npath_elements.reverse()\n\npath = source.get_user_path()\nif len(path_elements) > 0:\n    path = f"{path}/{'/'.join(path_elements)}"\nreturn {\n    "path": path\n}	goauthentik.io/sources/ldap/default-dn-path
a9542637-6489-4735-903f-4bf1c0ea4788	authentik default LDAP Mapping: Name	return {\n    "name": ldap.get("name"),\n}	goauthentik.io/sources/ldap/default-name
e9d041c7-972e-4829-a8c3-e0b6427cfea5	authentik default LDAP Mapping: mail	return {\n    "email": ldap.get("mail"),\n}	goauthentik.io/sources/ldap/default-mail
b3ad3ed9-ddde-4172-8a66-cdc38d49e321	authentik default Active Directory Mapping: sAMAccountName	return {\n    "username": ldap.get("sAMAccountName"),\n}	goauthentik.io/sources/ldap/ms-samaccountname
502281b9-21a1-4f10-9706-252437dde321	authentik default Active Directory Mapping: userPrincipalName	return {\n    "attributes": {\n        "upn": list_flatten(ldap.get("userPrincipalName")),\n    },\n}	goauthentik.io/sources/ldap/ms-userprincipalname
8c5e0b94-e1ca-459e-9ed9-00c3eddbe17e	authentik default Active Directory Mapping: givenName	return {\n    "attributes": {\n        "givenName": list_flatten(ldap.get("givenName")),\n    },\n}	goauthentik.io/sources/ldap/ms-givenName
31394959-a140-4472-a0d6-a3bf47fc9270	authentik default Active Directory Mapping: sn	return {\n    "attributes": {\n        "sn": list_flatten(ldap.get("sn")),\n    },\n}	goauthentik.io/sources/ldap/ms-sn
d0acaeef-ea4d-4450-b25b-04a5b551b06d	authentik default OpenLDAP Mapping: uid	return {\n    "username": ldap.get("uid"),\n}	goauthentik.io/sources/ldap/openldap-uid
8a0eb409-1820-4294-a4ba-2cc931e052f4	authentik default OpenLDAP Mapping: cn	return {\n    "name": ldap.get("cn"),\n}	goauthentik.io/sources/ldap/openldap-cn
af77f8dc-7b76-4388-b122-792fdf2d507f	authentik default OAuth Mapping: Proxy outpost	# This mapping is used by the authentik proxy. It passes extra user attributes,\n# which are used for example for the HTTP-Basic Authentication mapping.\nreturn {\n    "ak_proxy": {\n        "user_attributes": request.user.group_attributes(request),\n        "is_superuser": request.user.is_superuser,\n    }\n}	goauthentik.io/providers/proxy/scope-proxy
ac60030e-2a2a-4647-8e0e-eb25cd155f0c	authentik default SAML Mapping: Name	return request.user.name	goauthentik.io/providers/saml/name
612824b7-05d1-47ee-b625-be5c06136ead	authentik default SAML Mapping: Email	return request.user.email	goauthentik.io/providers/saml/email
af61e520-8e8f-4711-ac69-0d989420ca54	authentik default SAML Mapping: Username	return request.user.username	goauthentik.io/providers/saml/username
b47e69fe-d549-4420-8f92-e762c5a1e7e1	authentik default SCIM Mapping: User	# Some implementations require givenName and familyName to be set\ngivenName, familyName = request.user.name, " "\nformatted = request.user.name + " "\n# This default sets givenName to the name before the first space\n# and the remainder as family name\n# if the user's name has no space the givenName is the entire name\n# (this might cause issues with some SCIM implementations)\nif " " in request.user.name:\n    givenName, _, familyName = request.user.name.partition(" ")\n    formatted = request.user.name\n\n# photos supports URLs to images, however authentik might return data URIs\navatar = request.user.avatar\nphotos = None\nif "://" in avatar:\n    photos = [{"value": avatar, "type": "photo"}]\n\nlocale = request.user.locale()\nif locale == "":\n    locale = None\n\nemails = []\nif request.user.email != "":\n    emails = [{\n        "value": request.user.email,\n        "type": "other",\n        "primary": True,\n    }]\nreturn {\n    "userName": request.user.username,\n    "name": {\n        "formatted": formatted,\n        "givenName": givenName,\n        "familyName": familyName,\n    },\n    "displayName": request.user.name,\n    "photos": photos,\n    "locale": locale,\n    "active": request.user.is_active,\n    "emails": emails,\n}	goauthentik.io/providers/scim/user
10c04d0b-e983-486e-8894-510418ab1ad1	authentik default SCIM Mapping: Group	return {\n    "displayName": group.name,\n}	goauthentik.io/providers/scim/group
4baabf26-5810-492a-9e4f-e49f29fc05f8	authentik default SAML Mapping: User ID	return request.user.pk	goauthentik.io/providers/saml/uid
b7634a1e-27cb-4fca-ba7a-8555d06ffbbd	authentik default SAML Mapping: Groups	for group in request.user.ak_groups.all():\n    yield group.name	goauthentik.io/providers/saml/groups
e872aeb8-88ba-4df9-aceb-1bd7ffbf0bdd	authentik default SAML Mapping: WindowsAccountname (Username)	return request.user.username	goauthentik.io/providers/saml/ms-windowsaccountname
56d6a3a3-0db3-46be-8867-9a50a2f240a1	authentik default OAuth Mapping: OpenID 'openid'	# This scope is required by the OpenID-spec, and must as such exist in authentik.\n# The scope by itself does not grant any information\nreturn {}	goauthentik.io/providers/oauth2/scope-openid
bcb90078-cb86-44da-ac13-c8269e41fa8d	authentik default OAuth Mapping: OpenID 'email'	return {\n    "email": request.user.email,\n    "email_verified": False\n}	goauthentik.io/providers/oauth2/scope-email
b1d6b19f-137a-487a-ae80-d2c48c4b2372	authentik default OAuth Mapping: OpenID 'profile'	return {\n    # Because authentik only saves the user's full name, and has no concept of first and last names,\n    # the full name is used as given name.\n    # You can override this behaviour in custom mappings, i.e. `request.user.name.split(" ")`\n    "name": request.user.name,\n    "given_name": request.user.name,\n    "preferred_username": request.user.username,\n    "nickname": request.user.username,\n    "groups": [group.name for group in request.user.ak_groups.all()],\n}	goauthentik.io/providers/oauth2/scope-profile
b645d4e7-6b33-45f7-98a4-0de13a631b6b	authentik default OAuth Mapping: Application Entitlements	entitlements = [entitlement.name for entitlement in request.user.app_entitlements(provider.application)]\nreturn {\n    "entitlements": entitlements,\n    "roles": entitlements,\n}	goauthentik.io/providers/oauth2/scope-entitlements
cde1194b-5cc4-4bae-81e9-0e6a3a95b8cc	authentik default OAuth Mapping: OpenID 'offline_access'	# This scope grants the application a refresh token that can be used to refresh user data\n# and let the application access authentik without the users interaction\nreturn {}	goauthentik.io/providers/oauth2/scope-offline_access
117ccf48-4751-439e-9815-b83c0a378a14	authentik default Kerberos User Mapping: Multipart principals as service accounts	from authentik.core.models import USER_PATH_SERVICE_ACCOUNT, UserTypes\n\nlocalpart, _ = principal.rsplit("@", 1)\nis_service_account = "/" in localpart\nattrs = {}\nif is_service_account:\n    attrs = {\n        "type": UserTypes.SERVICE_ACCOUNT,\n        "path": USER_PATH_SERVICE_ACCOUNT,\n    }\nreturn attrs	goauthentik.io/sources/kerberos/user/default/multipart-principals-as-service-accounts
e055df2c-9b90-46dd-b1ba-e8a512c15b9b	authentik default Kerberos User Mapping: Ignore other realms	localpart, realm = principal.rsplit("@", 1)\nif realm.upper() != source.realm.upper():\n    raise SkipObject\nreturn {}	goauthentik.io/sources/kerberos/user/default/ignore-other-realms
93afae7a-dabd-4d8c-9f64-99e874b39a4e	authentik default Kerberos User Mapping: Ignore system principals	localpart, realm = principal.rsplit("@", 1)\ndenied_prefixes = ["kadmin/", "krbtgt/", "K/M", "WELLKNOWN/", "kiprop/", "changepw/"]\nfor prefix in denied_prefixes:\n    if localpart.lower().startswith(prefix.lower()):\n        raise SkipObject\nreturn {}	goauthentik.io/sources/kerberos/user/default/ignore-system-principals
01391fa9-75ca-481a-b093-9d0dbfa3dc3d	authentik default Kerberos User Mapping: Add realm as group	localpart, realm = principal.rsplit("@", 1)\nreturn {\n    "groups": [realm.upper()]\n}	goauthentik.io/sources/kerberos/user/realm-as-group
