COPY public.authentik_policies_expression_expressionpolicy (policy_ptr_id, expression) FROM stdin;
715137b2-bf9f-4c51-acd4-c2808d2f57cc	from authentik.core.models import (\n    USER_ATTRIBUTE_CHANGE_EMAIL,\n    USER_ATTRIBUTE_CHANGE_NAME,\n    USER_ATTRIBUTE_CHANGE_USERNAME\n)\nprompt_data = request.context.get("prompt_data")\n\nif not request.user.group_attributes(request.http_request).get(\n    USER_ATTRIBUTE_CHANGE_EMAIL, request.http_request.tenant.default_user_change_email\n):\n    if prompt_data.get("email") != request.user.email:\n        ak_message("Not allowed to change email address.")\n        return False\n\nif not request.user.group_attributes(request.http_request).get(\n    USER_ATTRIBUTE_CHANGE_NAME, request.http_request.tenant.default_user_change_name\n):\n    if prompt_data.get("name") != request.user.name:\n        ak_message("Not allowed to change name.")\n        return False\n\nif not request.user.group_attributes(request.http_request).get(\n    USER_ATTRIBUTE_CHANGE_USERNAME, request.http_request.tenant.default_user_change_username\n):\n    if prompt_data.get("username") != request.user.username:\n        ak_message("Not allowed to change username.")\n        return False\n\nreturn True
888fa87b-7e79-4b75-9108-627eb5d7d71f	# Check if we''ve not been given a username by the external IdP\n# and trigger the enrollment flow\nreturn 'username' not in context.get('prompt_data', {})
6a630074-06da-4f71-ae40-881502e61bb3	# This policy ensures that this flow can only be used when the user\n# is in a SSO Flow (meaning they come from an external IdP)\nreturn ak_is_sso_flow
bbd4e1fd-63fa-412f-b513-98090d5fc8d1	flow_plan = request.context.get("flow_plan")\nif not flow_plan:\n    return True\n# If the user does not have a backend attached to it, they haven't\n# been authenticated yet and we need the password stage\nreturn not hasattr(flow_plan.context.get("pending_user"), "backend")
da6f6d38-21a3-48dc-a0d7-c8799b64490f	# This policy ensures that this flow can only be used when the user\n# is in a SSO Flow (meaning they come from an external IdP)\nreturn ak_is_sso_flow
7585451a-84a4-401c-b813-024707cf8d5d	# This policy sets the user for the currently running flow\n# by injecting "pending_user"\nakadmin = ak_user_by(username="akadmin")\ncontext["flow_plan"].context["pending_user"] = akadmin\nreturn True
36f778d0-b595-42c0-a1bf-eeceff7541c5	# This policy ensures that the setup flow can only be\n# executed when the admin user doesn''t have a password set\nakadmin = ak_user_by(username="akadmin")\nreturn not akadmin.has_usable_password()
297907c1-ba90-4a1a-bbeb-0e82dc953e58	# This policy ensures that the setup flow can only be\n# used one time\nfrom authentik.flows.models import Flow, FlowAuthenticationRequirement\nFlow.objects.filter(slug="initial-setup").update(\n    authentication=FlowAuthenticationRequirement.REQUIRE_SUPERUSER,\n)\nreturn True
